import re
import logging


class SysCommand(object):
    def __init__(self, executor):
        self._executor = executor

    def kill_process(self, process_id):
        pass

    def get_process_id_by_tcp_port(self, port):
        pass

    def get_app_path(self, app_name):
        return self._executor.execute("which {}".format(app_name))

    def mkdir(self, *args):
        pass

    def pip_list(self, python_path):
        output = self._executor.execute("{} -m pip list --format freeze".format(python_path))
        logging.debug("got original pip list output: {}".format(repr(output)))
        filtered_output = self._remove_escape_sequences(output)
        pattern = re.compile(r"([a-zA-Z][a-zA-Z\d\-]+)==(\d[.\d]*\d)")
        packages = pattern.findall(filtered_output)
        return dict(packages)

    def list_only_files(self, folder, executor=None):
        executor = executor or self._executor
        output = executor.execute("ls -l {} |grep ^-".format(folder))
        logging.debug("got original pip list output: {}".format(repr(output)))
        lines = output.split('\r')
        files = []
        for line in lines:
            data = line.strip()
            if data and data.startswith('-'):
                files.append(data.split(' ')[-1])
        return files

    @classmethod
    def get_system_information(cls, executor):
        return executor.execute("uname -a")

    @classmethod
    def _covert_args_to_arguments(cls, *args):
        return ' '.join(args)

    @classmethod
    def _remove_escape_sequences(cls, input_str):
        ansi_escape_patterns = [
            r'\x1b\[\??\d\d[a-zA-Z][a-zA-Z]?(?=\s)',
            r'\x1b\[\??\d+;\d+[a-zA-Z]',
            r'\x1b\[\??\d\d[a-zA-Z]',
            r'\x1b\[\d?[a-zA-Z]'
        ]
        target = input_str
        for pattern in ansi_escape_patterns:
            compiled_pattern = re.compile(pattern)
            target = compiled_pattern.sub('', target)
        return target


class CygwinCommand(SysCommand):
    _CYGWIN_BIN_PATH = "/cygdrive/../bin/"

    def __init__(self, executor):
        super(CygwinCommand, self).__init__(executor)

    def mkdir(self, *args):
        cmd = self._CYGWIN_BIN_PATH + "mkdir {}".format(self._covert_args_to_arguments(*args))
        return self._executor.execute(cmd)

    def rm(self, *args):
        cmd = self._CYGWIN_BIN_PATH + "rm {}".format(self._covert_args_to_arguments(*args))
        return self._executor.execute(cmd)

    def get_app_path(self, app_name):
        return self._executor.execute(self._CYGWIN_BIN_PATH + "which {}".format(app_name))

    def kill_process(self, process_id):
        cmd = "taskkill /PID {} /F".format(process_id)
        return self._executor.execute(cmd)

    def get_process_id_by_tcp_port(self, port):
        cmd = r"netstat -a -o|awk '$2 ~ /:" + str(port) + "$/ {print $5}'"
        return self._executor.execute(cmd).split('\r')


class LinuxCommand(SysCommand):
    def __init__(self, executor):
        super(LinuxCommand, self).__init__(executor)

    def mkdir(self, *args):
        cmd = "mkdir {}".format(self._covert_args_to_arguments(*args))
        return self._executor.execute(cmd)

    def rm(self, *args):
        cmd = "rm {}".format(self._covert_args_to_arguments(*args))
        return self._executor.execute(cmd)

    def get_app_path(self, app_name):
        return self._executor.execute("which {}".format(app_name))

    def kill_process(self, process_id):
        cmd = "kill -9 {}".format(process_id)
        return self._executor.execute(cmd)

    def get_process_id_by_tcp_port(self, port):
        cmd = r"netstat -a -p|awk '$4 ~ /:" + str(port) + "$/ {print $7}'"
        pid_with_program_name_lines = self._executor.execute(cmd).split('\r')
        return [pid_with_program_name.split('/')[0] for pid_with_program_name in pid_with_program_name_lines]
